"use strict";

import Selectable from "approot/global/selectable";

angular
	.module("irtech.netcity.school.meals")
	.controller("ListDishesCtrl", ($scope, dishesRepository, $http, $q, $alerts, $routeParams, $dialogs, $appLoader, $uibModal) => {

		$scope.$parent.page = {
			title: "Блюда"
		}

		angular.extend($scope, {
			paging: {
				page: 1,
				pageSize: 20,
				totalcount: 0
			}
		});

		$.extend($scope, {
			language: language,
			data: {
				dishes: [],
				selection: new Selectable()
			},
			state: {
				dataReady: false,
				emptyData: false,
				viewReady: true
			}
		});

		//редактировать
		$scope.edit = (dish) => {
			let modalInstance = $uibModal.open({
				templateUrl: '/static/dist/app/school/meals/dishes/edit/template.html',
				controller: 'EditDishesCtrl',
				backdrop: false,
				keyboard: false,
				resolve: {
					dish: () => angular.copy(dish),
					mode: () => new Object({edit: true})
				}
			});
			modalInstance.result.then(() => $scope.load());
			modalInstance.closed.then(() => $scope.load());
		}

		//добавить
		$scope.add = (dish) => {
			let modalInstance = $uibModal.open({
				templateUrl: '/static/dist/app/school/meals/dishes/edit/template.html',
				controller: 'EditDishesCtrl',
				backdrop: false,
				keyboard: false,
				resolve: {
					dish: dish,
					mode: () => new Object({create: true})
				}
			});
			modalInstance.result.then((dish) => $scope.load());
			modalInstance.closed.then(() => $scope.load());
		}

		//удалить
		$scope.remove = (dish) => {
			$.show.confirmation(`Удалить блюдо "${dish.name}"?`)
				.then(function() {
					dishesRepository.remove(dish.id)
						.then(() => {
							$scope.load();
						});
				});
		};

		//загрузка данных
		$scope.load = () => {
			const params = {
				page: $scope.paging.page,
				pageSize: $scope.paging.pageSize
			};

			dishesRepository.getAll(params).then((dishes) => {
				// paging
				$scope.paging.totalcount = dishes.totalcount;
				$scope.paging.show = $scope.paging.totalcount > $scope.paging.pageSize && $scope.paging.page > 0;

				$scope.data.dishes = dishes;
				$scope.data.selection.selected = false;
				$scope.state.emptyData = !dishes.length;
				$scope.state.dataReady = true;
				$appLoader.hide();
			});

		}

		$scope.load();
	});



