"use strict";

import Selectable from "approot/global/selectable";

angular
	.module("irtech.netcity.school.meals")
	.controller("ListProductsCtrl", ($scope, productsRepository, $http, $q, $alerts, $routeParams, $dialogs, $appLoader, $uibModal) => {


		$scope.$parent.page = {
			title: "Продукты"
		}

		angular.extend($scope, {
			paging: {
				page: 1,
				pageSize: 20,
				totalcount: 0
			}
		});

		$.extend($scope, {
			language: language,
			data: {
				products: [],
				selection: new Selectable()
			},
			state: {
				dataReady: false,
				emptyData: false,
				viewReady: true
			}
		});

		// показать модальный диалог
		$scope.$showModal = (options) => {
			// опции по умолчанию
			let defOpts = {
				templateUrl: "/static/dist/app/school/meals/products/edit/template.html",
				controller: "EditProductCtrl",
				size: "md"
			};

			options = options || {}; // если нет опций, то проинициализировать пустым объектом
			let modalOpts = $.extend({}, defOpts, options);

			const modalInstance = $uibModal.open(modalOpts); // инициализация модального диалога

			return modalInstance;
		};

		// добавить продукт
		$scope.add = () => {

			let options = {
				resolve: {
					product: () => null
				}
			};

			const modalInstance = $scope.$showModal(options);

			modalInstance.result.then(() => { $scope.load(); });
		};

		// редактировать продукт
		$scope.edit = (product) => {
			let options = {
				resolve: {
					product: () => angular.copy(product)
				}
			};

			const modalInstance = $scope.$showModal(options);

			modalInstance.result.then(() => { $scope.load(); });
		};

		// удалить продукт
		$scope.remove = (product) => {
			$.show.confirmation(`Удалить продукт "${product.name}"?`)
				.then(function() {
					productsRepository.remove(product.id).then(() => { $scope.load(); });
				});
		};

		//загрузка данных
		$scope.load = () => {
			const params = {
				page: $scope.paging.page,
				pageSize: $scope.paging.pageSize
			};

			productsRepository.getAll(params).then((products) => {
				$scope.data.products = products;

				// сброс выбора
				$scope.data.selection.selected = null;

				// paging
				$scope.paging.totalcount = products.totalcount;
				$scope.paging.show = $scope.paging.totalcount > $scope.paging.pageSize && $scope.paging.page > 0;

				$scope.state.emptyData = !products.length;
				$scope.state.dataReady = true;
				$appLoader.hide();
			});

		}

		$scope.load();
	});



