"use strict";

angular
	.module("irtech.netcity.school.meals")
	.controller("EditProductCtrl",
		($scope, productsRepository, $http, $q, $alerts, $routeParams, $dialogs, $appLoader, $uibModalInstance, product) => {
			$scope.header = "Редактирование продукта";

			$scope.isAdd = !product;

			$.extend($scope,
			{
				language: language,
				data: {
					product: product || {}
				}
			});

			$scope.save = () => {
				let product = $scope.data.product;

				if ($scope.isAdd) {
					if (!product.name) {
						$alerts.error("не заполнено название продукта");
						return;
					}
					productsRepository.create(product).then(() => { $uibModalInstance.close(product); });
				} else {
					productsRepository.edit(product).then(() => { $uibModalInstance.close(product); });
				}
			};

			$scope.cancel = () => {
				$uibModalInstance.dismiss("cancel");
			};
		});


