"use strict";

import Selectable from "approot/global/selectable";

angular
	.module("irtech.netcity.school.meals")
	.controller("EditDishContentCtrl",
		($scope, dishesRepository, productsRepository, $http, $q, $alerts, $routeParams, $dialogs, $appLoader, $uibModalInstance, dishContent, mode, dishId) => {
			$.extend($scope, {
				language: language,
				data: {
					dishId: dishId,
					dishContent: dishContent,
					products: [],
					selection: new Selectable()
				},
				state: {
					dataReady: false,
					emptyData: false,
					viewReady: true
				},
				mode: mode,
				header: mode.edit ? "Редактировать ингредиент" : "Добавить ингредиент"
			});

			$scope.load = () => {
				const params = {
					page: -1,
					pageSize: -1
				};

				productsRepository.getAll(params).then((products) => {
					$scope.data.products = products;
					$appLoader.hide();
				});
			}

			$scope.cancel = () => {
				$uibModalInstance.dismiss("cancel");
			};

			$scope.onChange = () => {
				$scope.state.wasChanged = true;
			}

			$scope.save = (valid, content) => {
				if (valid) {
					if (content) {
						dishesRepository.editContent($scope.data.dishId, content)
							.then((content) => {
								$scope.state.dataReady = true;
								$appLoader.hide();
								$uibModalInstance.close(content);
							});
					} 
					else {
						dishesRepository.addContent($scope.data.dishId, $scope.data.dishContent)
							.then((content) => {
								$scope.state.dataReady = true;
								$appLoader.hide();
								$uibModalInstance.close(content);
							});
					}
				}
			}
			$scope.load();
		}
	)
	.controller("EditDishesCtrl",
		($scope, dishesRepository, $http, $q, $alerts, $routeParams, $dialogs, $appLoader, $uibModal, $uibModalInstance, dish, mode) => {

			$.extend($scope, {
				language: language,
				data: {
					dish: dish,
					selection: new Selectable()
				},
				state: {
					dataReady: false,
					emptyData: false,
					viewReady: true,
					contentWasChanged: false
				},
				mode: mode,
				header: mode.edit ? "Редактировать блюдо" : "Добавить блюдо"
			});

			$scope.cancel = () => {
				if ($scope.state.contentWasChanged) {
					$uibModalInstance.close($scope.data.dish);
				} 
				else {
					$uibModalInstance.dismiss("cancel");
				}
			};

			$scope.save = (valid, dish) => {
				if (valid) {
					if (dish) {
						dishesRepository.edit(dish)
							.then((dish) => {
								$scope.state.dataReady = true;
								$appLoader.hide();
								$uibModalInstance.close(dish);
							});
					} 
					else {
						dishesRepository.create($scope.data.dish.item).then((dish) => {
							$scope.state.dataReady = true;
							$appLoader.hide();
							$scope.mode.edit = true;
							$scope.mode.create = false;
							$scope.data.dish.item = dish;
						});
					}
				}
			}

			$scope.addProduct = (dishContent) => {
				let modalInstance = $uibModal.open({
					templateUrl: '/static/dist/app/school/meals/dishes/edit/editDishContentTemplate.html',
					controller: 'EditDishContentCtrl',
					resolve: {
						dishContent: dishContent,
						dishId: $scope.data.dish.item.id,
						mode: () => new Object({create: true})
					}
				});
				modalInstance.result.then((dishContent) => {
					$scope.state.contentWasChanged = true;
					$scope.data.dish.item.contents = _.union($scope.data.dish.item.contents, [dishContent]);
					$scope.$applyAsync(() => $appLoader.hide());
				});				
			}

			$scope.editProduct = (dishContent) => {
				let modalInstance = $uibModal.open({
					templateUrl: '/static/dist/app/school/meals/dishes/edit/editDishContentTemplate.html',
					controller: 'EditDishContentCtrl',
					resolve: {
						dishContent: angular.copy(dishContent),
						dishId: $scope.data.dish.item.id,
						mode: () => new Object({edit: true})
					}
				});
				modalInstance.result.then((dishContent) => {
					$scope.state.contentWasChanged = true;
					$scope.data.dish.item.contents = _.union(_.reject($scope.data.dish.item.contents, (item) => item.id === dishContent.id), [dishContent]);
					$scope.$applyAsync(() => $appLoader.hide());
				});
			}

			$scope.removeProduct = (dishContent) => {
				$.show.confirmation(`Удалить ингредиент "${dishContent.product.name}"?`)
					.then(function() {
						dishesRepository.removeContent(dishContent.id)
							.then(() => {
								$scope.state.contentWasChanged = true;
								$scope.data.selection.selected = false;
								$scope.data.dish.item.contents = _.reject($scope.data.dish.item.contents, (item) => item.id === dishContent.id);
								$scope.$applyAsync(() => $appLoader.hide());
							});
					});
			}

			$scope.onChange = () => {
				$scope.state.contentWasChanged = true;
			}

			$appLoader.hide();



		});


