"use strict";

import Selectable from "approot/global/selectable";
import * as mailsRefs from "approot/school/meals/refs.js";

require("./../add/addMenuCtrl.js");

angular
	.module("irtech.netcity.school.meals")
	.controller("ListMenuCtrl", ($scope, refsRepository, menusRepository, $http, $q, $alerts, $routeParams, $dialogs, $appLoader, $location, $uibModal) => {

		$scope.$parent.page = {
			title: "Меню"
		}

		$.extend($scope, {
			language: language,
			data: {
				menus: [],
				selection: new Selectable()
			},
			refs: {
				ageRangesIdx: _.indexBy(mailsRefs.default.ageRanges, "id"),
				stayRegimesIdx: _.indexBy(mailsRefs.default.stayRegimes, "id"),
				seasonTypesIdx: {}
			},
			state: {
				dataReady: false,
				emptyData: false,
				viewReady: true
			}
		});

		//редактировать
		$scope.add = () => {
			let modalInstance = $uibModal.open({
				templateUrl: "/static/dist/app/school/meals/menu/add/template.html",
				controller: "AddMenuCtrl",
				resolve: {}
			}); 
			modalInstance.result.then($scope.load);
		}

		//редактировать
		$scope.edit = (menu) => {
			$location.path(`/menu/${menu.id}/details`);
		}

		//удалить
		$scope.remove = (menu) => {
			$.show.confirmation(`Удалить меню "${menu.name}"?`)
				.then(function() {
					menusRepository.remove(menu.id).then(() => {
						$scope.load();
					});
				});
		};

		const seasonTypesReady = refsRepository.getSeasonTypes().then((seasonTypes) => {
			$scope.refs.seasonTypesIdx = _.indexBy(seasonTypes, "key");
		});
		const statusTypesReady = refsRepository.getStatusTypes().then((statusTypes) => {
			$scope.refs.statusTypesIdx = _.indexBy(statusTypes, "key");
		});
		const refsReady = $q.all([seasonTypesReady, statusTypesReady]);

		//загрузка данных
		$scope.load = () => {
			menusRepository.getAll(appContext.yearId)
				.then((menus) => {
					$scope.data.menus = menus;
					$scope.data.selection.dropSelect();

					refsReady.then(() => {
						_.each($scope.data.menus, (menu) => {
							menu.douGroupAge = $scope.refs.ageRangesIdx[menu.douGroupAgeId];
							menu.douGroupRegime = $scope.refs.stayRegimesIdx[menu.douGroupRegimeId];
							menu.season = $scope.refs.seasonTypesIdx[menu.season].name;
							menu.status = $scope.refs.statusTypesIdx[menu.status].name;
						});
						$scope.state.emptyData = !menus.length;
						$scope.state.dataReady = true;
						$appLoader.hide();
					});

					
				});

		}

		$scope.export = () => {
			postTo({path: "/webapi/modules/food/schoolmenu/file", formParams: { method: "GET" }, params: { schoolYearId: appContext.yearId }});
		}

		$(document).on("click", ".menu-export-btn", $scope.export);



		$scope.load();
	});



