const module = angular
	.module("irtech.netcity.school.meals",
	[
		"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap",
		"ngFileUpload", "ui.tree", "irtech.netcity.common", "irtech.netcity.ui-components"
	]);


require("./repository.js");
require("./dishes/list/listDishesCtrl.js");
require("./dishes/edit/addDishesCtrl.js");
require("./menu/list/listMenuCtrl.js");
require("./menu/details/detailsMenuCtrl.js");
require("./products/list/listProducts.js");
require("./products/edit/editProductCtrl.js");

	module
	.config(($routeProvider, $locationProvider) => {
		$routeProvider
			.when("/dishes/", {
				templateUrl: "/static/dist/app/school/meals/dishes/list/template.html",
				controller: "ListDishesCtrl"
			})
			.when("/dishes/edit/", {
				templateUrl: "/static/dist/app/school/meals/dishes/edit/template.html",
				controller: "EditDishesCtrl"
			})
			.when("/menu/", {
				templateUrl: "/static/dist/app/school/meals/menu/list/template.html",
				controller: "ListMenuCtrl"
			})
			.when("/menu/:menuId/details", {
				templateUrl: "/static/dist/app/school/meals/menu/details/template.html",
				controller: "DetailsMenuCtrl"
			})
			.when("/products/", {
				templateUrl: "/static/dist/app/school/meals/products/list/template.html",
				controller: "ListProductsCtrl"
			})
			.otherwise({
				templateUrl: "/static/dist/app/school/meals/menu/list/template.html",
				controller: "ListMenuCtrl"
			});

		$locationProvider.hashPrefix('');
		$locationProvider.html5Mode({
			enabled: true,
			requireBase: true
		});
	});



