"use strict";

angular
	.module("irtech.netcity.school.meals")
	.controller("EditDayMenuContentCtrl", ($scope, dishesRepository, dayMenusRepository, $http, $q, $alerts, $routeParams, $dialogs, $appLoader, $uibModalInstance, dayMenu, content) => {

		$scope.mode = {
			create: !content,
			edit: content && content.id
		};

		$scope.header = "Редактирование состава меню";

		$.extend($scope, {
			language: language,
			data: {
				dayMenu: dayMenu,
				content: content,
				refs: {
					dishes: []
				}
			},
			state: {
				dataReady: false,
				viewReady: false
			}
		});

		dishesRepository.getAll().then((dishes) => {
			if (dishes) {
				$scope.data.refs.dishes = dishes;
				$scope.state.dataReady = true;
				$scope.state.viewReady = true;
			} else {
				$uibModalInstance.dismiss('cancel');
			}
		});

		$scope.save = (valid) => {
			if (valid) {
				dayMenusRepository.addOrEditContent(0, $scope.data.dayMenu.id, $scope.data.content).then((savedContent) => {
					$uibModalInstance.close(savedContent);
				});
			}
		}

		$scope.cancel = () => {
			$uibModalInstance.dismiss('cancel');
		}

	});



