class mealRefs {
	get ageRanges() {
		return [
			{id: 1, name: "От 2 месяцев до 1 года"},
			{id: 2, name: "От 1 года до 3 лет"},
			{id: 3, name: "От 3 лет до 7 лет"},
			{id: 4, name: "От 1 года до 7 лет"},
			{id: 5, name: "От 3 лет до 5 лет"},
			{id: 6, name: "От 5 лет до 7 лет"},
			{id: 7, name: "От 4 лет до 5 лет"},
			{id: 8, name: "От 4 лет до 7 лет"},
			{id: 9, name: "От 2 лет до 3 лет"},
			{id: 10, name: "От 3 лет до 6 лет"},
			{id: 11, name: "От 5 лет до 6 лет"},
			{id: 12, name: "От 2 лет до 7 лет"},
			{id: 13, name: "От 2 лет до 4 лет"},
			{id: 14, name: "От 2 лет до 5 лет"},
			{id: 15, name: "От 6 лет до 7 лет"},
			{id: 16, name: "От 3 до 8 лет"}
		];
	}
	
	get stayRegimes() {
		return [
			{id:1, name: "полный день"},
			{id:2, name: "продлённый день"},
			{id:3, name: "кратковременного пребывания"},
			{id:4, name: "круглосуточного пребывания"}
		];
	}
}

const instance = new mealRefs();

export default instance;



