"use strict";

import { BaseRepository } from "approot/global/repository.js";

class ProductsRepository extends BaseRepository {
	getAll(params) {
		params = params || {};
		return this.$http.get("/webapi/modules/food/products", { params }).then((response) => {
			const products = response.data;
			if (response.headers("count")) {
				products.totalcount = parseInt(response.headers("count"));
			}

			return products;
		});
	}

	create(product) {
		return this.$http.put("/webapi/modules/food/products", product)
			.then((response) => {
				this.$alerts.success("добавлен");
				return response.data;
			})
			.catch(this.handleError);
	}

	edit(product) {
		return this.$http.post("/webapi/modules/food/products", product)
			.then((response) => {
				this.$alerts.success("отредактирован");
				return response.data;
			})
			.catch(this.handleError);
	}

	remove(id) {
		return this.$http.delete(`/webapi/modules/food/products?id=${id}`)
			.then(() => { this.$alerts.success("удален"); })
			.catch(this.handleError);
	}
}

class MenusRepository extends BaseRepository {
	get(menuId) {
		return this.$http.get("/webapi/modules/food/schoolmenu", { params: { id: menuId } }).then((response) => {
			return response.data;
		});
	}
	add(menu) {
		return this.$http.put("/webapi/modules/food/schoolmenu", menu).then((response) => {
			return response.data;
		});
	}
	remove(menuId) {
		return this.$http.delete(`/webapi/modules/food/schoolmenu?id=${menuId}`).then((response) => {
			this.$alerts.success("Меню успешно удалено");
			return response.data;
		});
	}
	save(menu) {
		return this.$http.post("/webapi/modules/food/schoolmenu", menu)
			.then((response) => {
				this.$alerts.success("Меню успешно изменено");
				return response.data;
			})
			.catch(this.handleError);
	}
	getAll() {
		return this.$http.get("/webapi/modules/food/schoolmenu", { params: { } }).then((response) => {
			return response.data;
		});
	}
}

class DishesRepository extends BaseRepository {
	getAll(params) {
		params = params || {};
		return this.$http.get("/webapi/modules/food/dishes", { params }).then((response) => {
			const dishes = response.data;
			if (response.headers("count")) {
				dishes.totalcount = parseInt(response.headers("count"));
			}
			return dishes;
		})
		.catch(this.handleError);
	}
	create(dish) {
		return this.$http.put("/webapi/modules/food/dishes", dish)
			.then((response) => {
				this.$alerts.success("Добавлено блюдо");
				return response.data;
			})
			.catch(this.handleError);
	}

	edit(dish) {
		return this.$http.post("/webapi/modules/food/dishes", dish)
			.then((response) => {
				this.$alerts.success("Блюдо отредактировано");
				return response.data;
			})
			.catch(this.handleError);
	}

	remove(id) {
		return this.$http.delete(`/webapi/modules/food/dishes?id=${id}`)
			.then(() => { this.$alerts.success("Блюдо удалено"); })
			.catch(this.handleError);
	}

	addContent(dishId, content) {
		return this.$http.post(`/webapi/modules/food/dishes/${dishId}/contents`, content)
			.then((response) => {
				this.$alerts.success("Добавлен продукт для блюда");
				return response.data;
			})
			.catch(this.handleError);
	}

	editContent(dishId, content) {
		return this.$http.post(`/webapi/modules/food/dishes/${dishId}/contents`, content)
			.then((response) => {
				this.$alerts.success("Изменены данные о продукте для блюда");
				return response.data;
			})
			.catch(this.handleError);
	}

	removeContent(dishId, contentId) {
		return this.$http.delete(`/webapi/modules/food/dishes/${dishId}/contents`, contentId)
			.then((response) => {
				this.$alerts.success("Удален продукт у блюда");
				return response.data;
			})
			.catch(this.handleError);
	}
}

class DayMenusRepository extends BaseRepository {
	getMenuDayMenus(menuId) {
		return this.$http.get(`/webapi/modules/food/schoolmenu/${menuId}/daymenu`)
			.then((response) => { return response.data; })
			.catch(this.handleError);
	}

	add(menuId, dayMenu) {
		return this.$http.put(`/webapi/modules/food/schoolmenu/${menuId}/daymenu`, dayMenu)
			.then((response) => { return response.data; })
			.catch(this.handleError);
	}

	edit(menuId, dayMenu) {
		return this.$http.post(`/webapi/modules/food/schoolmenu/${menuId}/daymenu`, dayMenu).catch(this.handleError);
	}

	remove(menuId, id) {
		return this.$http.delete(`/webapi/modules/food/schoolmenu/${menuId}/daymenu?id=${id}`)
		.then(() => this.$alerts.success("Меню на день успешно удалено"))
		.catch(this.handleError);
	}

	addOrEditContent(menuId, dayMenuId, content) {
		return this.$http.post(`/webapi/modules/food/schoolmenu/${menuId}/daymenu/${dayMenuId}/contents`, content)
			.then((response) => { return response.data; })
			.catch(this.handleError);
	}

	removeContent(menuId, dayMenuId, id) {
		return this.$http.delete(`/webapi/modules/food/schoolmenu/${menuId}/daymenu/${dayMenuId}/contents?id=${id}`)
			.then(() => this.$alerts.success("Блюдо успешно удалено из состава"))
			.catch(this.handleError);
	}
}

