angular
	.module("irtech.netcity.school.meals")
		.factory('productsRepository', ($http, $dialogs, $alerts) => new ProductsRepository($http, $dialogs, $alerts))
		.factory('menusRepository', ($http, $dialogs, $alerts) => new MenusRepository($http, $dialogs, $alerts))
		.factory('dayMenusRepository', ($http, $dialogs, $alerts) => new DayMenusRepository($http, $dialogs, $alerts))
		.factory('dishesRepository', ($http, $dialogs, $alerts) => new DishesRepository($http, $dialogs, $alerts))
		.factory('refsRepository', ($http, $dialogs, $alerts) => new RefsRepository($http, $dialogs, $alerts))
		.factory('eatingTimesRepository', ($http, $dialogs, $alerts) => new EatingTimesRepository($http, $dialogs, $alerts))
;


