"use strict";

import Selectable from "approot/global/selectable";
import * as mailsRefs from "approot/school/meals/refs.js";

require("./editEatingTime/editEatingTimeCtrl.js");
require("./editDayMenu/editDayMenuCtrl.js");
require("./editDayMenuContent/editDayMenuContentCtrl.js");

angular
	.module("irtech.netcity.school.meals")
	.controller("DetailsMenuCtrl", ($scope, refsRepository, menusRepository, dayMenusRepository, eatingTimesRepository, $http, $q, $alerts, $routeParams, $dialogs, $appLoader, $uibModal) => {

		$scope.$parent.page = {
			parent: {
				title: "Меню",
				href: `menu/`
			},
			back: { history: true },
			title: "Информация по меню"
		}

		$.extend($scope, {
			language: language,
			data: {
				menuId:  $routeParams.menuId,
				menu: null,
				selection: {
					eatingTimes: new Selectable(),
					dayMenus: new Selectable()
				}
			},
			refs: {
				ageRanges: mailsRefs.default.ageRanges,
				stayRegimes: mailsRefs.default.stayRegimes,
				eatingTypes: [],
				seasonTypes: []
			},
			state: {
				dataReady: false,
				emptyData: false,
				viewReady: true
			}
		});

		$scope.addEatingTime = () => {
			let modalInstance = $uibModal.open({
				templateUrl: "/static/dist/app/school/meals/menu/details/editEatingTime/template.html",
				controller: "EditEatingTimeCtrl",
				resolve: {
					menu: () => $scope.data.menu,
					eatingTime: () => null
				}
			});
			modalInstance.closed.then($scope.load);
			modalInstance.result.then($scope.load);
		};

		$scope.editEatingTime = (eatingTime) => {
			let modalInstance = $uibModal.open({
				templateUrl: "/static/dist/app/school/meals/menu/details/editEatingTime/template.html",
				controller: "EditEatingTimeCtrl",
				resolve: {
					menu: () => $scope.data.menu,
					eatingTime: () => eatingTime
				}
			});
			modalInstance.closed.then($scope.load);
			modalInstance.result.then($scope.load);
		};

		$scope.removeEatingTime = (eatingTime) => {
			var typeInfo = _.find($scope.refs.eatingTypes, (type) => { return type.key === eatingTime.type.key; });

			$.show.confirmation(`Удалить прием пищи "${typeInfo.name}" из расписания ?`)
				.then(function() {
					eatingTimesRepository.remove($scope.data.menuId, eatingTime.id).then($scope.load);
				});
		};

		$scope.addDayMenu = () => {
			let modalInstance = $uibModal.open({
				templateUrl: "/static/dist/app/school/meals/menu/details/editDayMenu/template.html",
				controller: "EditDayMenuCtrl",
				resolve: {
					menu: () => $scope.data.menu,
					dayMenu: () => {}
				}
			});
			modalInstance.closed.then($scope.load);
			modalInstance.result.then($scope.load);
		};

		$scope.editDayMenu = (dayMenu) => {
			let modalInstance = $uibModal.open({
				templateUrl: "/static/dist/app/school/meals/menu/details/editDayMenu/template.html",
				controller: "EditDayMenuCtrl",
				resolve: {
					menu: () => $scope.data.menu,
					dayMenu: () => angular.copy(dayMenu)
				}
			});

			modalInstance.closed.then($scope.load);
			modalInstance.result.then($scope.load);
		};

		$scope.removeDayMenu = (dayMenu) => {
			dayMenusRepository.remove($scope.data.menuId, dayMenu.id).then($scope.load);
		};

		//редактировать
		$scope.save = () => {
			menusRepository.save($scope.data.menu);
		}

		$scope.lazySave = _.debounce($scope.save, 1500);

		const sum = (collection, fieldRef) => {
			var sum = _.chain(collection)
				.map(fieldRef)
				.reduce((memo, val) => { return memo + val; }, 0);

			sum = parseFloat(Math.round(sum * 100) / 100).toFixed(2);

			return sum;
		}

		// эталонный вес
		const referenceWeight = 100;

		// рассчитывает компоненты блюда на каждые сто грамм
		let prepareDayMenu = (dayMenu) => {
			// информация по блюдам
			var contents = [...dayMenu.contents];

			_.each(contents,
				(content) => {
					// считать из расчета на каждые сто грамм
					var coeff = content.weight / referenceWeight;

					if (content.dish) {
						var dish = content.dish;
						
						dish.proteins = dish.proteins * coeff;
						dish.fats = dish.fats * coeff;
						dish.carbohydrate = dish.carbohydrate * coeff;
						dish.caloricValue = dish.caloricValue * coeff;
						dish.vitaminC = dish.vitaminC * coeff;
					}
				});

			var preparedDayMenu = {
				contents: contents
			};

			return preparedDayMenu;
		}

		const calcTotals = (dayMenu) => {
			var preparedDayMenu = prepareDayMenu(dayMenu);

			dayMenu.totals = {
				weight: sum(preparedDayMenu.contents, c => c.weight),
				caloricValue: sum(preparedDayMenu.contents, c => c.dish.caloricValue),
				carbohydrate: sum(preparedDayMenu.contents, c => c.dish.carbohydrate),
				fats: sum(preparedDayMenu.contents, c => c.dish.fats),
				proteins: sum(preparedDayMenu.contents, c => c.dish.proteins),
				vitaminC: sum(preparedDayMenu.contents, c => c.dish.vitaminC)
			};
		};

		//загрузка данных
		$scope.load = () => {
			const refsLoaded = refsRepository.getEatingTypes().then((eatingTypes) => {
				$scope.refs.eatingTypes = eatingTypes;
				$scope.refs.eatingTypes.idx = _.indexBy($scope.refs.eatingTypes, "key");
			});

			const seasonTypesLoaded = refsRepository.getSeasonTypes().then((seasonTypes) => {
				$scope.refs.seasonTypes = seasonTypes;
			});

			const statusTypesLoaded = refsRepository.getStatusTypes().then((statusTypes) => {
				$scope.refs.statusTypes = statusTypes;
			});

			const menuLoaded = menusRepository.get($scope.data.menuId).then((menu) => $scope.data.menu = menu);

			$q.all([refsLoaded, seasonTypesLoaded, statusTypesLoaded, menuLoaded]).then(() => {
				_.each($scope.data.menu.dayMenu, (dm) => {
					calcTotals(dm);
					dm.eatingTime.type = $scope.refs.eatingTypes.idx[dm.eatingTime.type];
				});

				_.each($scope.data.menu.eatingTimes, (et) => {
					et.type = $scope.refs.eatingTypes.idx[et.type];

					et.start = new Date(et.start);
					et.end = new Date(et.end);
					et.startStr = moment(et.start).format("LT");
					et.endStr = moment(et.end).format("LT");
				});

				$scope.state.dataReady = true;
				$appLoader.hide();
			});
			$scope.data.selection.eatingTimes.dropSelect();
			$scope.data.selection.dayMenus.dropSelect();
		}

		$scope.load();
	});



