"use strict";

angular
	.module("irtech.netcity.school.meals")
	.controller("AddMenuCtrl", ($scope, menusRepository, $uibModalInstance) => {

		$scope.header = "Создание нового меню";

		$.extend($scope, {
			language: language,
			data: {
				menu: {}
			},
			state: {
				dataReady: true,
				viewReady: true
			}
		});

		$scope.create = () => {
			menusRepository.add($scope.data.menu).then((saved) => {
				$uibModalInstance.close(saved);
			});
		}

		$scope.add = () => {
			menusRepository.add($scope.data.menu).then((saved) => {
				$uibModalInstance.close(saved);
			});
		}

		$scope.remove = () => {
			menusRepository.remove($scope.data.menu).then((saved) => {
				$uibModalInstance.close(saved);
			});
		}

		$scope.cancel = () => {
			$uibModalInstance.dismiss('cancel');
		}

	});



